// 1. Ambil data sebagai Array (menggunakan .all())
const rawData = $input.all().map(item => item.json); 
const JAM_MASUK_STANDAR = "08:00";
const JAM_PULANG_STANDAR = "14:30";
const LIMIT_MENIT = 8 * 60; // 480 Menit

// 2. Fungsi Helper untuk konversi waktu ke menit
function toMinutes(timeStr) {
    if (!timeStr) return 0;
    const [h, m] = timeStr.split(':').map(Number);
    return (h * 60) + m;
}

// 3. Fungsi hitung selisih "DI LUAR JAM"
function hitungSelisih(jenisAbsen, jamAbsen) {
    const menitAbsen = toMinutes(jamAbsen);

    if (jenisAbsen.includes("MASUK")) {
        const menitStandar = toMinutes(JAM_MASUK_STANDAR);
        return menitAbsen > menitStandar ? menitAbsen - menitStandar : 0;
    } 

    if (jenisAbsen.includes("PULANG")) {
        const menitStandar = toMinutes(JAM_PULANG_STANDAR);
        return menitAbsen < menitStandar ? menitStandar - menitAbsen : 0;
    }

    return 0;
}

// 4. Proses Akumulasi
const akumulasiPegawai = {};

// Sekarang rawData sudah pasti berbentuk Array
rawData.forEach(item => {
    if (item.Tanggal && item["Jenis Absen"] && item["Jenis Absen"].includes("DI LUAR JAM")) {
        const id = item.ID;
        const nama = item.Nama;

        if (!akumulasiPegawai[id]) {
            akumulasiPegawai[id] = { id: id, nama: nama, totalMenit: 0 };
        }

        akumulasiPegawai[id].totalMenit += hitungSelisih(item["Jenis Absen"], item.Jam);
    }
});

// 5. Filter pegawai yang akumulasinya >= 8 Jam
const hasilFilter = Object.values(akumulasiPegawai)
    .filter(p => p.totalMenit >= LIMIT_MENIT)
    .map(p => ({
        id: p.id,
        nama: p.nama,
        akumulasiWaktu: `${Math.floor(p.totalMenit / 60)}j ${p.totalMenit % 60}m`,
        totalMenit: p.totalMenit
    }));

const daftarPesan = hasilFilter.map(p => {
    return {
        id: p.id,
        nama: p.nama,
        pesan: `🔔 *PERINGATAN AKUMULASI WAKTU*\n` +
               `───────────────────\n` +
               `Yth. Bapak/Ibu *${p.nama}*,\n\n` +
               `Melalui pesan otomatis ini, kami menginformasikan bahwa akumulasi waktu "Di Luar Jam" (Keterlambatan & Pulang Cepat) Anda telah mencapai batas maksimum.\n\n` +
               `📊 *Detail Akumulasi:*\n` +
               `• Total Waktu: *${p.akumulasiWaktu}*\n` +
               `• Ambang Batas: 8 Jam (480 Menit)\n\n` +
               `Sesuai dengan peraturan yang berlaku, akumulasi ini setara dengan 1 hari kerja. Mohon segera melakukan konfirmasi ke bagian Kepegawaian untuk klarifikasi atau tindak lanjut administratif.\n\n` +
               `_Terima kasih atas perhatiannya._\n` +
               `───────────────────\n` +
               `*Sistem Absensi Digital*`
    };
});

return daftarPesan;

const inputDate = $input.first().json.timestamp;
const dateObj = new Date(inputDate);

// Opsi untuk format lokal
const options = {
  timeZone: 'Asia/Makassar',
  year: 'numeric',
  month: '2-digit',
  day: '2-digit',
  hour: '2-digit',
  minute: '2-digit',
  second: '2-digit',
  hour12: false
};

// Mengambil string lokal secara utuh
const localString = dateObj.toLocaleString('en-GB', options);

// Memisahkan tanggal dan jam (Format en-GB: DD/MM/YYYY, HH:mm:ss)
const [datePart, timePart] = localString.split(', ');
const [day, month, year] = datePart.split('/');

// Susun ulang tanggal ke format YYYY-MM-DD agar rapi
const tanggal = `${year}-${month}-${day}`;
const jam = timePart;

return [{
  json: {
    tanggal: tanggal,
    jam: jam
  }
}];

// 1. Ambil data dari input
const pegawai = $input.all().map(item => item.json);
const logAbsen = $('Get Log Masuk').all().map(item => item.json);
const tanggal = $('Read Tanggal Masuk').first().json.tanggal;
const jamTarget = $('Read Tanggal Masuk').first().json.jam; // Sesuaikan jam pengingat

// 2. Buat Set ID pegawai yang sudah absen masuk hari ini
//    (mencakup "MASUK" dan "DI LUAR JAM MASUK" — keduanya tetap dianggap sudah absen)
const sudahAbsenIds = new Set(
  logAbsen
    .filter(log =>
      log.Tanggal === tanggal &&
      (log['Jenis Absen'] === 'MASUK' || log['Jenis Absen'] === 'DI LUAR JAM MASUK')
    )
    .map(log => String(log.ID))
);

// 3. Filter pegawai AKTIF yang BELUM absen masuk
const belumAbsen = pegawai.filter(p =>
  String(p.Status).toUpperCase() === 'AKTIF' &&
  !sudahAbsenIds.has(String(p.id))
);

// 4. Format output — satu item per pegawai (untuk dikirim notifikasi individual)
return belumAbsen.map(p => {
  const pesan =
    `⚠️ *PENGINGAT ABSENSI MASUK*\n\n` +
    `Halo *${p.username || p.Nama}*,\n` +
    `Hingga pukul *${jamTarget}* WITA, Anda tercatat *BELUM melakukan absensi MASUK* hari ini.\n\n` +
    `Mohon segera melakukan absensi melalui aplikasi.`;

  return {
    json: {
      id: p.id,
      username: p.username || p.Nama,
      NIP: p.NIP,
      Jabatan: p.Jabatan,
      Status: p.Status,
      tanggal,
      sudahAbsen: false,
      pesan
    }
  };
});

const inputDate = $input.first().json.timestamp;
const dateObj = new Date(inputDate);

// Opsi untuk format lokal
const options = {
  timeZone: 'Asia/Makassar',
  year: 'numeric',
  month: '2-digit',
