// 1. Ambil data dari input
const pegawai   = $input.all().map(item => item.json);
const logAbsen  = $('Cek Log Pulang').all().map(item => item.json); // ← PERBAIKI INI
const tanggal   = $('Read Tanggal Pulang').first().json.tanggal;
const jamTarget = $('Read Tanggal Pulang').first().json.jam;

// 2. Filter log hanya untuk tanggal hari ini
const logHariIni = logAbsen.filter(log => log.Tanggal === tanggal);

// 3. ID yang sudah absen MASUK hari ini
const sudahMasukIds = new Set(
  logHariIni
    .filter(log =>
      log['Jenis Absen'] === 'MASUK' ||
      log['Jenis Absen'] === 'DI LUAR JAM MASUK'
    )
    .map(log => String(log.ID))
);

// 4. ID yang sudah absen PULANG hari ini
const sudahPulangIds = new Set(
  logHariIni
    .filter(log =>
      log['Jenis Absen'] === 'PULANG'             ||
      log['Jenis Absen'] === 'DI LUAR JAM PULANG' ||
      log['Jenis Absen'] === 'PULANG LUAR'
    )
    .map(log => String(log.ID))
);

// 5. Filter pegawai AKTIF yang sudah MASUK tapi belum PULANG
const belumPulang = pegawai.filter(p =>
  String(p.Status).toUpperCase() === 'AKTIF' &&
  sudahMasukIds.has(String(p.id)) &&
  !sudahPulangIds.has(String(p.id))
);

// 6. Format output — satu item per pegawai
return belumPulang.map(p => {
  const pesan =
    `⚠️ *PENGINGAT ABSENSI PULANG*\n\n` +
    `Halo *${p.username || p.Nama}*,\n` +
    `Anda tercatat sudah hadir, namun *belum melakukan absensi PULANG*.\n` +
    `Batas jam pulang: 14:30 WITA.`;
  return {
    json: {
      id         : p.id,
      username   : p.username || p.Nama,
      NIP        : p.NIP,
      Jabatan    : p.Jabatan,
      Status     : p.Status,
      tanggal,
      sudahMasuk : true,
      sudahPulang: false,
      pesan
    }
  };
});

const items = $input.all().map(item => item.json);

return {
  json: {
    data_pegawai: items // Semua item sekarang berada di dalam satu array ini
  }
};

const method=$input.first().json.headers?.['x-forwarded-method']||$input.first().json.method||'';
if(method==='OPTIONS'){$execution.respond({statusCode:200,headers:{'Access-Control-Allow-Origin':'*','Access-Control-Allow-Methods':'GET,POST,OPTIONS','Access-Control-Allow-Headers':'Content-Type,ngrok-skip-browser-warning,Accept'},body:''});return[];}
return $input.all();

const q=$input.first().json.query||{};
const userId=(q.user_id||'').toString().trim();
if(!userId) return [{json:{ok:false,message:'Parameter user_id wajib diisi.'}}];
return [{json:{ok:true,user_id:userId}}];

const rows=$input.all().map(i=>i.json);
// Jika tidak ada data atau data kosong (row kosong dari Sheets)
if(!rows.length||!rows[0].user_id){
  return [{json:{ok:true,data:[],count:0}}];
}
const docs=rows.map(r=>({
  user_id:      r.user_id      || '',
  nama_dokumen: r.nama_dokumen || r.nama || '—',
  jenis:        (r.jenis||r.kategori||'DOKUMEN').toUpperCase(),
  link:         r.link||r.webViewLink||r.url||'',
  tanggal:      r.tanggal||r.uploadedAt||'',
  tambah_oleh:  r.tambah_oleh||''
}));
return [{json:{ok:true,data:docs,count:docs.length}}];

const body = $('Webhook Update Status').first().json.body || {};
const userId    = body.user_id    ? String(body.user_id) : null;
const statusBaru= (body.status_baru || 'AKTIF').toUpperCase();
const alasan    = body.alasan || 'Update manual';

if (!userId) {
  return [{ json: { ok:false, error:'user_id wajib diisi' } }];
}
const allowed = ['AKTIF','NONAKTIF','CUTI','SAKIT'];
if (!allowed.includes(statusBaru)) {
  return [{ json: { ok:false, error:`Status tidak valid. Pilihan: ${allowed.join(', ')}` } }];
}
return [{ json: { ok:true, user_id:userId, status_baru:statusBaru, alasan } }];

const validasi = $('Validasi Input').first().json;
const userId   = validasi.user_id;
const statusBaru = validasi.status_baru;
const alasan     = validasi.alasan;

const rows = $('Get User List').all().map(i => i.json);
const idx  = rows.findIndex(r => String(r.id||r.ID||'') === userId);

if (idx < 0) {
  return [{ json: { ok:false, error:`Pegawai dengan ID ${userId} tidak ditemukan`, rowNum:null } }];
}

const peg = rows[idx];
const statusLama = (peg.Status || peg.status || 'AKTIF').toUpperCase();

// Row number di sheet = idx + 2 (1 header + 1-based index)
const rowNumber = idx + 2;

return [{ json: {
  ok: true,
  row_number : rowNumber,
  user_id    : userId,
  nama       : peg.nama || peg.Nama || peg.username || '',
  status_lama: statusLama,
  status_baru: statusBaru,
  alasan     : alasan,
  kolom_status: Object.keys(peg).findIndex(k => k.toLowerCase()==='status') + 1
} }];

const method = $input.first().json.headers?.['x-forwarded-method']
            || $input.first().json.method || '';
if (method === 'OPTIONS') {
  $execution.respond({
    statusCode: 200,
    headers: {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type, ngrok-skip-browser-warning, Accept'
    },
    body: ''
  });
  return [];
}
return $input.all();

// Support opsional: ?user_id=xxx  → kembalikan hanya 1 pegawai
// Tanpa parameter                  → kembalikan semua pegawai
const query  = $('User-List').first().json.query || {};
const userId = query.user_id ? String(query.user_id).trim() : null;

let rows = $input.all().map(i => i.json);

if (userId) {
  rows = rows.filter(r =>
    String(r.id || r.ID || '').trim() === userId ||
    String(r.username || '').trim() === userId
  );
  if (!rows.length) {
    return [{ json: { ok: false, error: 'Pegawai tidak ditemukan', user_id: userId } }];
  }
  // Kembalikan data pegawai tunggal
  return [{ json: {
    ok    : true,
    single: true,
    id        : String(rows[0].id || rows[0].ID || ''),
    nama      : rows[0].Nama      || rows[0].nama      || rows[0].username || '',
    username  : rows[0].Username  || rows[0].username  || '',
    nip       : rows[0].NIP       || rows[0].nip       || '',
    jabatan   : rows[0].Jabatan   || rows[0].jabatan   || '',
    status    : rows[0].Status    || rows[0].status    || 'AKTIF',
    jam_masuk : rows[0].jam_masuk || rows[0].Jam_Masuk || null,
    jam_pulang: rows[0].jam_pulang|| rows[0].Jam_Pulang|| null
  } }];
}

// Kembalikan semua dalam format array rows
return [{ json: { ok: true, data: rows, total: rows.length } }];

const method = $input.first().json.headers?.['x-forwarded-method']
            || $input.first().json.method || '';
if (method === 'OPTIONS') {
  $execution.respond({
    statusCode: 200,
    headers: {
      'Access-Control-Allow-Origin': '*',
      'Access-Control-Allow-Methods': 'GET, POST, OPTIONS',
      'Access-Control-Allow-Headers': 'Content-Type, ngrok-skip-browser-warning, Accept'
    },
    body: ''
  });
  return [];
}
return $input.all();

// ╔══════════════════════════════════════════════════════════════════╗
// ║   FORMAT PESAN REKAP v6 — BAPPERIDA Sumba Barat                  ║
// ║   Mode HARIAN: tampilkan jam masuk & pulang aktual per pegawai   ║
// ║   Mode RANGE : tampilkan ringkasan akumulasi seperti sebelumnya  ║
// ║   JAM_KERJA_WAJIB dibaca dari data pegawai (bukan 150 hardcoded) ║
// ╚══════════════════════════════════════════════════════════════════╝

const body         = $input.first().json.body || $input.first().json;
const dari         = body.dari         || '—';
const sampai       = body.sampai       || '—';
const chatId       = String(body.chat_id || '');
const pegawai      = body.pegawai      || [];
const isHarian     = body.is_harian    === true || dari === sampai;
const tanggalLabel = body.tanggal_label || (dari === sampai ? dari : `${dari} s.d. ${sampai}`);

// JAM_KERJA_WAJIB: ambil dari data pegawai pertama (dikirim oleh frontend, sudah dinamis).
// Fallback 150 hanya jika tidak ada data sama sekali.
const JAM_KERJA_WAJIB = parseFloat(
  pegawai.find(p => p.jamKerjaWajib > 0)?.jamKerjaWajib || 150
);

// ── Ringkasan total ──
let totMasuk=0, totPulang=0, totLambat=0, totCepat=0;
let totIzin=0, totSakit=0, totTugas=0;
let pernahLambat=0, pernahCepat=0, tepatWaktu=0;

pegawai.forEach(p => {
  const lambat    = Number(p.lambat      ?? p.di_luar_masuk  ?? 0);
  const pulangCpt = Number(p.pulangCepat ?? p.di_luar_pulang ?? 0);
  totMasuk   += Number(p.masuk  || 0);
  totPulang  += Number(p.pulang || 0);
  totLambat  += lambat;
  totCepat   += pulangCpt;
  totIzin    += Number(p.izin   || 0);
  totSakit   += Number(p.sakit  || 0);
  totTugas   += Number(p.tugas  || 0);
  if (lambat    > 0) pernahLambat++;
  if (pulangCpt > 0) pernahCepat++;
  if (lambat === 0 && pulangCpt === 0 &&
      (Number(p.masuk||0) > 0 || Number(p.pulang||0) > 0)) tepatWaktu++;
});

let msg = `📊 *REKAP ABSENSI — BAPPERIDA SUMBA BARAT*\n`;

if (isHarian) {
  // ══════════════════════════════════════
  // MODE HARIAN: tampilkan jam per pegawai
  // ══════════════════════════════════════
  const totHadir   = pegawai.filter(p => { const k=(p.dataExcelRow||{})['Keterangan']||''; return k==='Hadir'||k.includes('Terlambat')||k.includes('Cepat'); }).length;
  const totAlpa    = pegawai.filter(p => ((p.dataExcelRow||{})['Keterangan']||'').includes('Tidak Hadir')).length;

  msg += `🗓️ Tanggal: ${tanggalLabel}\n`;
  msg += `👥 Total Pegawai: ${pegawai.length}\n`;
  msg += `━━━━━━━━━━━━━━━━━━\n`;
  msg += `✅ Hadir: ${totHadir}  ❌ Tidak Hadir: ${totAlpa}\n`;
  msg += `🙏 Izin: ${totIzin}  🤒 Sakit: ${totSakit}  💼 DL: ${totTugas}\n`;
  msg += `⏰ Terlambat: ${totLambat}  🏃 Pulang Cepat: ${totCepat}\n`;
  msg += `━━━━━━━━━━━━━━━━━━\n\n`;

  pegawai.forEach((p, idx) => {
    const row        = p.dataExcelRow || {};
    const jamMasuk   = row['Jam Masuk']  || p.jamMasuk  || '—';
    const jamPulang  = row['Jam Pulang'] || p.jamPulang || '—';
    const keterangan = row['Keterangan'] || '—';

    const ikonKet = keterangan.startsWith('Izin')          ? '🙏'
                  : keterangan.startsWith('Sakit')         ? '🤒'
                  : keterangan.startsWith('Tugas')         ? '💼'
                  : keterangan.includes('Tidak Hadir')     ? '❌'
                  : keterangan === 'Hadir'                 ? '✅'
                  : '⚠️';

    msg += `${idx+1}. *${p.nama}*  ${ikonKet} ${keterangan}\n`;
    msg += `   NIP: ${p.nip || '—'} | ${p.jabatan || '—'}\n`;
    msg += `   🟢 Masuk : *${jamMasuk}*\n`;
    msg += `   🔵 Pulang: *${jamPulang}*\n\n`;
  });

} else {
  // ══════════════════════════════════════
  // MODE RANGE: ringkasan akumulasi
  // ══════════════════════════════════════
  const totalJamHadir = pegawai.reduce((s,p) => s + parseFloat(p.jamHadir||0), 0);

  msg += `🗓️ Periode: ${tanggalLabel}\n`;
  msg += `👥 Total Pegawai: ${pegawai.length}\n`;
  msg += `⏱️ Jam Kerja Wajib: ${JAM_KERJA_WAJIB} jam/periode\n`;
  msg += `━━━━━━━━━━━━━━━━━━\n`;
  msg += `✅ Masuk: ${totMasuk}  🔵 Pulang: ${totPulang}\n`;
  msg += `🕐 Lambat: ${totLambat}  🏃 Pulang Cepat: ${totCepat}\n`;
  msg += `🙏 Izin: ${totIzin}  🤒 Sakit: ${totSakit}  💼 Tugas: ${totTugas}\n`;
  msg += `━━━━━━━━━━━━━━━━━━\n`;
  msg += `📈 *Kedisiplinan:* ✔️${tepatWaktu} tepat | ⚠️${pernahLambat} lambat | 🏃${pernahCepat} cepat\n`;
  msg += `⏱️ Total Jam Hadir: ${totalJamHadir.toFixed(1)} jam\n`;
  msg += `━━━━━━━━━━━━━━━━━━\n\n`;

  pegawai.forEach((p, idx) => {
    const lambat    = Number(p.lambat      ?? p.di_luar_masuk  ?? 0);
    const pulangCpt = Number(p.pulangCepat ?? p.di_luar_pulang ?? 0);
    const jh        = parseFloat(p.jamHadir    || 0);
    // Gunakan jamTdkHadir yang dikirim frontend (sudah dihitung dinamis),
    // fallback ke JAM_KERJA_WAJIB dinamis jika tidak ada.
    const jwajib    = parseFloat(p.jamKerjaWajib || JAM_KERJA_WAJIB);
    const jth       = parseFloat(p.jamTdkHadir ?? Math.max(0, jwajib - jh).toFixed(1));
    const akkL = p.akkLambatHHMM || p.akkLambat || '0m';
    const akkC = p.akkCepatHHMM  || p.akkCepat  || '0m';

    msg += `${idx+1}. *${p.nama}*\n`;
    msg += `   NIP: ${p.nip} | ${p.jabatan || '—'}\n`;
    msg += `   ⏱️ Hadir: ${jh.toFixed(1)}j | Tdk Hadir: ${jth.toFixed(1)}j (wajib: ${jwajib.toFixed(1)}j)\n`;

    const badges = [];
    if (Number(p.masuk  ||0) > 0) badges.push(`✅M:${p.masuk}`);
    if (Number(p.pulang ||0) > 0) badges.push(`🔵P:${p.pulang}`);
    if (lambat    > 0) badges.push(`🕐L:${lambat}×(${akkL})`);
    if (pulangCpt > 0) badges.push(`🏃C:${pulangCpt}×(${akkC})`);
    if (Number(p.izin  ||0) > 0) badges.push(`🙏I:${p.izin}`);
    if (Number(p.sakit ||0) > 0) badges.push(`🤒S:${p.sakit}`);
    if (Number(p.tugas ||0) > 0) badges.push(`💼DL:${p.tugas}`);

    if (badges.length === 0) {
      msg += `   ⬜ _Tidak ada data absensi pada periode ini_\n\n`;
    } else {
      msg += `   ${badges.join(' ')}\n\n`;
    }
  });
}

msg += `━━━━━━━━━━━━━━━━━━\n`;
msg += `_Dikirim otomatis via BAPPERIDA Absen Bot_`;

// ── Excel: gunakan dataExcelRow dari frontend jika ada ──
const dataExcel = pegawai.map((p, index) => {
  if (p.dataExcelRow) return p.dataExcelRow;

  // Fallback: mode range tanpa dataExcelRow dari frontend
  const lambat    = Number(p.lambat      ?? p.di_luar_masuk  ?? 0);
  const pulangCpt = Number(p.pulangCepat ?? p.di_luar_pulang ?? 0);
  const masuk     = Number(p.masuk  || 0);
  const pulang    = Number(p.pulang || 0);
  const izin      = Number(p.izin   || 0);
  const sakit     = Number(p.sakit  || 0);
