    nama    : j.Nama    || j.nama    || j.username || '—',
    jabatan : j.Jabatan || j.jabatan || '—',
    nip     : String(j.NIP || j.nip || '—'),
    status  : String(j.Status || j.status || 'AKTIF').toUpperCase(),
    urutan  : Number(j.no || j.No || idx) // ← pakai field `no`, fallback ke idx
  };
}).filter(u => u.id && u.status !== 'NONAKTIF');

// ══════════════════════════════════════════════
// 2. Inisialisasi map
// ══════════════════════════════════════════════
const map = {};
userList.forEach(u => {
  map[u.id] = {
    id: u.id, nama: u.nama, nip: u.nip, jabatan: u.jabatan, urutan: u.urutan,
    masuk: 0, pulang: 0, di_luar_masuk: 0, di_luar_pulang: 0,
    izin: 0, sakit: 0, tugas: 0,
    menit_terlambat: 0, menit_lebih_awal: 0,
    hadir_dates: new Set(),
    jamMasuk: '-', jamPulang: '-',
    all_masuk: 0, all_di_luar_masuk: 0, all_di_luar_pulang: 0,
    all_menit_terlambat: 0, all_menit_lebih_awal: 0
  };
});

// ══════════════════════════════════════════════
// 3. Ambil semua log
// ══════════════════════════════════════════════
const allRows = $('Get All Log').all();

// ══════════════════════════════════════════════
// 4a. ALL-TIME accumulation
// ══════════════════════════════════════════════
for (const r of allRows) {
  const id = String(r.json.ID || r.json.id || '').trim();
  if (!id || !map[id]) continue;
  const p   = map[id];
  const j   = String(r.json['Jenis Absen'] || r.json.jenis || '').toUpperCase().trim();
  const jam = toMenit(r.json.Jam || r.json.jam);

  if (j === 'MASUK') {
    p.all_masuk++;
  } else if (j === 'DI LUAR JAM MASUK') {
    p.all_di_luar_masuk++;
    if (jam !== null && jam > JAM_MASUK_STANDAR)
      p.all_menit_terlambat += (jam - JAM_MASUK_STANDAR);
  } else if (j === 'DI LUAR JAM PULANG') {
    p.all_di_luar_pulang++;
    if (jam !== null && jam < JAM_PULANG_STANDAR)
      p.all_menit_lebih_awal += (JAM_PULANG_STANDAR - jam);
  }
}

// ══════════════════════════════════════════════
// 4b. Statistik PERIODE
// ══════════════════════════════════════════════
let rows = allRows;
if (dari && sampai) {
  rows = rows.filter(r => {
    const t = String(r.json.Tanggal || r.json.tanggal || '');
    return t >= dari && t <= sampai;
  });
}

for (const r of rows) {
  const id = String(r.json.ID || r.json.id || '').trim();
  if (!id || !map[id]) continue;
  const p      = map[id];
  const j      = String(r.json['Jenis Absen'] || r.json.jenis || '').toUpperCase().trim();
  const jam    = toMenit(r.json.Jam || r.json.jam);
  const tgl    = String(r.json.Tanggal || '');
  const jamStr = String(r.json.Jam || r.json.jam || '').replace(/\s*WITA\s*/i, '').trim();

  const curNama = String(r.json.Nama || r.json.nama || '');
  if (curNama.length > p.nama.length) p.nama = curNama;

  if (j === 'MASUK') {
    p.masuk++;
    if (tgl) p.hadir_dates.add(tgl);
    if (jamStr) p.jamMasuk = jamStr;
  } else if (j === 'PULANG') {
    p.pulang++;
    if (jamStr) p.jamPulang = jamStr;
  } else if (j === 'DI LUAR JAM MASUK') {
    p.di_luar_masuk++;
    if (tgl) p.hadir_dates.add(tgl);
    if (jamStr) p.jamMasuk = jamStr;
    if (jam !== null && jam > JAM_MASUK_STANDAR)
      p.menit_terlambat += (jam - JAM_MASUK_STANDAR);
  } else if (j === 'DI LUAR JAM PULANG') {
    p.di_luar_pulang++;
    if (jamStr) p.jamPulang = jamStr;
    if (jam !== null && jam < JAM_PULANG_STANDAR)
      p.menit_lebih_awal += (JAM_PULANG_STANDAR - jam);
  } else if (j === 'PULANG LUAR') {
    p.pulang++;
    if (jamStr) p.jamPulang = jamStr;
  } else if (j === 'IZIN')                { p.izin++;  }
  else if   (j === 'SAKIT')               { p.sakit++; }
  else if   (j === 'TUGAS' || j === 'DL') { p.tugas++; }
}

// ══════════════════════════════════════════════
// 5. Finalisasi
// ══════════════════════════════════════════════
const pegawai = userList.map(u => {
  const p = map[u.id];

  const jmlHadirHari  = p.hadir_dates.size;
  const jamHadirMurni = jmlHadirHari * JAM_PER_HARI;
  const potonganJam   = (p.menit_terlambat + p.menit_lebih_awal) / 60;
  const jamHadir      = Math.max(0, jamHadirMurni - potonganJam);
  // jamTdkHadir sekarang relatif terhadap JAM_KERJA_WAJIB yang dinamis
  const jamTdkHadir   = Math.max(0, JAM_KERJA_WAJIB - jamHadir);

  // Disiplin masuk (tepat/terlambat)
  const totalMasukEntries = p.masuk + p.di_luar_masuk;
  const disiplinMasukPct  = totalMasukEntries > 0
    ? Math.round((p.masuk / totalMasukEntries) * 100) : null;

  // Kehadiran vs hari kerja (sudah termasuk izin/sakit/tugas sebagai hadir)
  const hariHadirTotal = p.hadir_dates.size + p.izin + p.sakit + p.tugas;
  const kehadiranPct   = HARI_KERJA_PERIODE > 0
    ? Math.min(100, Math.round(hariHadirTotal / HARI_KERJA_PERIODE * 100)) : null;

  // ALL-TIME disiplin
  const totalMasukAll  = p.all_masuk + p.all_di_luar_masuk;
  const disiplinAllPct = totalMasukAll > 0
    ? Math.round((p.all_masuk / totalMasukAll) * 100) : null;

  const disiplinPeriode = getDisiplin(disiplinMasukPct);
  const disiplinAllTime = getDisiplin(disiplinAllPct);
  const kehadiranInfo   = getKehadiran(kehadiranPct);

  return {
    id      : p.id,
    nama    : p.nama,
    nip     : p.nip,
    jabatan : p.jabatan,
    urutan  : p.urutan,
    jamMasuk      : p.jamMasuk,
    jamPulang     : p.jamPulang,
    masuk         : p.masuk,
    pulang        : p.pulang,
    lambat        : p.di_luar_masuk,
