    tugas         : p.tugas,
    akkLambat        : fmtMenit(p.menit_terlambat),
    akkCepat         : fmtMenit(p.menit_lebih_awal),
    akkLambatHHMM    : toHHMM(p.menit_terlambat),
    akkCepatHHMM     : toHHMM(p.menit_lebih_awal),
    totalAkkHHMM     : toHHMM(p.menit_terlambat + p.menit_lebih_awal),
    totalAkkMenit    : p.menit_terlambat + p.menit_lebih_awal,
    jamHadir         : jamHadir.toFixed(1),
    jamTdkHadir      : jamTdkHadir.toFixed(1),
    jamKerjaWajib    : JAM_KERJA_WAJIB,        // nilai dinamis (bukan 150)
    jamPerHari       : parseFloat(JAM_PER_HARI.toFixed(2)),
    hariHadir        : hariHadirTotal,
    hariKerja        : HARI_KERJA_PERIODE,
    kehadiranPct     : kehadiranInfo.pct,
    kehadiranLabel   : kehadiranInfo.label,
    kehadiranLevel   : kehadiranInfo.level,
    disiplinPct      : disiplinPeriode.pct,
    disiplinLabel    : disiplinPeriode.label,
    disiplinLevel    : disiplinPeriode.level,
    allMasuk              : p.all_masuk,
    allLambat             : p.all_di_luar_masuk,
    allPulangCepat        : p.all_di_luar_pulang,
    totalLambatAllHHMM    : toHHMM(p.all_menit_terlambat),
    totalCepatAllHHMM     : toHHMM(p.all_menit_lebih_awal),
    totalAkkAllHHMM       : toHHMM(p.all_menit_terlambat + p.all_menit_lebih_awal),
    totalAkkAllMenit      : p.all_menit_terlambat + p.all_menit_lebih_awal,
