if (accuracy > 500) return tolak('GPS_WEAK', `Sinyal GPS lemah (${Math.round(accuracy)}m). Coba di area terbuka.`);

const adaAltitude = gpsFp.has_altitude === true;
if (accuracy < 3 && !adaAltitude) return tolak('GPS_ACCURACY_TOO_PERFECT', `Akurasi ${accuracy.toFixed(1)}m terlalu sempurna tanpa data altitude.`);

if (gpsFp && typeof gpsFp === 'object') {
  const nullCount = [gpsFp.has_altitude===false,gpsFp.has_altitude_acc===false,gpsFp.has_heading===false,gpsFp.has_speed===false].filter(Boolean).length;
  if (nullCount >= 4 && accuracy <= 10) return tolak('GPS_FAKE_FINGERPRINT', 'Profil data GPS tidak lengkap. Nonaktifkan Fake GPS.');
}

if (!pegawai) return tolak('PEGAWAI_TIDAK_DITEMUKAN', 'ID Telegram Anda tidak terdaftar. Hubungi admin.');
const status = String(pegawai.Status || pegawai.status || 'AKTIF').toUpperCase();
if (status === 'NONAKTIF' || status === 'INACTIVE') return tolak('PEGAWAI_NONAKTIF', 'Akun Anda dinonaktifkan. Hubungi admin.');

if (isNaN(lat) || isNaN(lng)) return tolak('KOORDINAT_INVALID', 'Koordinat GPS tidak valid.');
if (lat === 0 && lng === 0) return tolak('KOORDINAT_NULL', 'Koordinat GPS 0,0 tidak valid.');

const jam = parseJamWITA(jamStr);
if (!jam) return tolak('JAM_INVALID', 'Format jam tidak valid.');
const totalMenit = jam.h * 60 + jam.m;

let jenisAbsen;
if      (totalMenit <= BATAS_MASUK)  jenisAbsen = 'MASUK';
else if (totalMenit <= TENGAH_HARI)  jenisAbsen = 'DI LUAR JAM MASUK';
else if (totalMenit <  BATAS_PULANG) jenisAbsen = 'DI LUAR JAM PULANG';
else                                 jenisAbsen = 'PULANG';

if (body.jenis_absen === 'PULANG LUAR' && body.skip_radius_check === true) jenisAbsen = 'PULANG LUAR';

if (jenisAbsen === 'PULANG LUAR') {
  return [{ json: {
    is_valid: true, jenis_absen: 'PULANG LUAR', nama_lokasi: 'Lapangan',
    periode_aktif: namaPeriodeAktif,
    keterangan: body.keterangan || 'Pulang dari lapangan',
    pegawai: { id: tgId, nama: pegawai?.nama||pegawai?.Nama||pegawai?.username||'', nip: pegawai?.NIP||pegawai?.nip||'', jabatan: pegawai?.Jabatan||pegawai?.jabatan||'' },
    log: { tanggal: tanggalIso, jam: jamStr.split(' ')[0], koordinat: `${lat},${lng}`, akurasi: accuracy }
  }}];
}

if (!lokasiItems.length) return tolak('LOKASI_TIDAK_ADA', 'Data lokasi kantor belum dikonfigurasi.');
const accuracyBuffer = Math.min(accuracy, 50);
let lokasiValid = null;
for (const lok of lokasiItems) {
  const jarak = haversine(lat, lng, parseFloat(lok.latitude), parseFloat(lok.longitude));
  if (jarak <= (parseFloat(lok.radius)||100) + accuracyBuffer) { lokasiValid = lok.Nama_Lokasi||lok.nama_lokasi||'Kantor'; break; }
}
if (!lokasiValid) {
  let jarakMin=Infinity, namaMin='';
  for (const lok of lokasiItems) {
    const j=haversine(lat,lng,parseFloat(lok.latitude),parseFloat(lok.longitude));
    if(j<jarakMin){jarakMin=j;namaMin=lok.Nama_Lokasi||lok.nama_lokasi||'Kantor';}
  }
  return tolak('DILUAR_RADIUS', `Anda berada ${Math.round(jarakMin)}m dari ${namaMin}. Absen hanya bisa di area kantor.`);
}

const GRP_MASUK  = ['MASUK','DI LUAR JAM MASUK'];
const GRP_PULANG = ['PULANG','DI LUAR JAM PULANG','PULANG LUAR'];

// Filter sudah ketat di Supabase (ID + Tanggal) → pakai langsung
const absenHariIniFiltered = absenHariIni.filter(r => {
  const rTgl = String(r['Tanggal']||r.tanggal||'').trim();
  const rId  = String(r['ID']||r.id||'').trim();
  return rTgl === tanggalIso && rId === String(tgId);
});

// Anti race-condition: cek duplikasi ketat berdasarkan jam (dalam 30 detik)
const jamSubmit = parseHHMM(jamStr);
const duplikat = absenHariIniFiltered.some(r => {
  const jamLog = parseHHMM(String(r['Jam']||r.jam||''));
  if (jamLog === null || jamSubmit === null) return false;
  return Math.abs(jamLog - jamSubmit) <= 1; // dalam 1 menit = duplikat
});
if (duplikat) return tolak('DUPLIKAT_ABSEN', 'Permintaan absen duplikat. Silakan tunggu sebentar.');

const sudahMasuk  = absenHariIniFiltered.some(r => GRP_MASUK.includes(String(r['Jenis Absen']||r.jenis||'').toUpperCase().trim()));
const sudahPulang = absenHariIniFiltered.some(r => GRP_PULANG.includes(String(r['Jenis Absen']||r.jenis||'').toUpperCase().trim()));
if (GRP_MASUK.includes(jenisAbsen)  && sudahMasuk)  return tolak('SUDAH_ABSEN', 'Anda sudah melakukan absen masuk hari ini.');
if (GRP_PULANG.includes(jenisAbsen) && sudahPulang) return tolak('SUDAH_ABSEN', 'Anda sudah melakukan absen pulang hari ini.');

const isPulang = ['PULANG','DI LUAR JAM PULANG','PULANG LUAR'].includes(jenisAbsen);
const adaMasuk = absenHariIniFiltered.some(r => { const j=String(r['Jenis Absen']||r.jenis||'').toUpperCase().trim(); return j==='MASUK'||j==='DI LUAR JAM MASUK'; });
if (isPulang && !adaMasuk) return tolak('BELUM_MASUK', 'Anda belum melakukan absen masuk hari ini.');

return terima(jenisAbsen, lokasiValid);

const saved    = $input.first().json;
const body     = $('Absen').first().json.body || {};
const validasi = $('Validasi Absen').first().json;
const pgw      = $('Get Pegawai Absen').first().json;

const nama      = validasi.pegawai?.nama    || pgw.username || pgw.Nama || '—';
const nip       = validasi.pegawai?.nip     || pgw.NIP      || '—';
const tanggal   = validasi.log?.tanggal     || body.tanggal_iso || saved.Tanggal || '—';
const jamRaw    = validasi.log?.jam         || body.jam         || saved.Jam     || '—';
const lokasi    = validasi.nama_lokasi      || saved.Lokasi     || '—';
const jenisAbsen= validasi.jenis_absen      || saved['Jenis Absen'] || '—';
const chatId    = String(body.user?.id || '');
const periodeAktif = validasi.periode_aktif || null;

const jamBersih = jamRaw.replace(/\s*WITA\s*/gi, '').trim().slice(0,5);

// Hitung info terlambat/lebih awal
function parseHHMM(s) {
  const m = String(s || '').match(/(\d{1,2}):(\d{2})/);
  if (!m) return null;
  return parseInt(m[1]) * 60 + parseInt(m[2]);
}

// Ambil jam batas dari Validasi (via Get Jam Absen + Get Periode Absen)
let jamAbsenRow = {};
try {
  const jamRows = $('Get Jam Absen').all().map(i => i.json);
  jamAbsenRow = jamRows.find(r => r.key === 'jam_absen_global') || jamRows[0] || {};
} catch(_) {}

let BATAS_MASUK_STR  = jamAbsenRow.masuk  || '08:00';
let BATAS_PULANG_STR = jamAbsenRow.pulang || '14:30';
let sumberJam = 'Global';

// Cek periode aktif
try {
  const periodeRows = $('Get Periode Absen').all().map(i => i.json);
  for (const row of periodeRows) {
    const dari   = String(row.dari   || '').trim();
    const sampai = String(row.sampai || dari).trim();
    const masuk  = String(row.masuk  || '').trim();
    const pulang = String(row.pulang || '').trim();
    const nama_p = String(row.nama   || '').trim();
    if (!dari || !masuk || !pulang) continue;
    if (tanggal >= dari && tanggal <= sampai) {
      BATAS_MASUK_STR  = masuk;
  BATAS_PULANG_STR = pulang;
      sumberJam = nama_p || 'Periode Khusus';
      break;
    }
  }
} catch(_) {}

const BATAS_MASUK  = parseHHMM(BATAS_MASUK_STR);
const BATAS_PULANG = parseHHMM(BATAS_PULANG_STR);
const mJam = parseHHMM(jamBersih);

// Hitung keterlambatan / pulang lebih awal
let infoWaktu = '';
if (jenisAbsen === 'DI LUAR JAM MASUK' && mJam !== null && BATAS_MASUK !== null) {
  const telat = mJam - BATAS_MASUK;
  const j = Math.floor(telat / 60), m = telat % 60;
  infoWaktu = j > 0 ? `⏰ Terlambat ${j} jam ${m} menit` : `⏰ Terlambat ${m} menit`;
} else if (jenisAbsen === 'DI LUAR JAM PULANG' && mJam !== null && BATAS_PULANG !== null) {
  const cepat = BATAS_PULANG - mJam;
  const j = Math.floor(cepat / 60), m = cepat % 60;
  infoWaktu = j > 0 ? `⚡ Pulang lebih awal ${j} jam ${m} menit` : `⚡ Pulang lebih awal ${m} menit`;
}

const jenisDisplay =
  jenisAbsen === 'DI LUAR JAM MASUK'  ? '⏰ TERLAMBAT' :
  jenisAbsen === 'DI LUAR JAM PULANG' ? '⚡ Pulang Lebih Awal' :
  jenisAbsen === 'PULANG LUAR'        ? '🏃 Pulang dari Lapangan' :
  jenisAbsen === 'MASUK'              ? '✅ Masuk Tepat Waktu' :
  jenisAbsen === 'PULANG'             ? '🔵 Pulang Tepat Waktu' :
  jenisAbsen;

const jamBatasInfo = `⏱ Batas: Masuk ≤${BATAS_MASUK_STR} | Pulang ≥${BATAS_PULANG_STR}${periodeAktif ? ' ('+periodeAktif+')' : ' (Global)'}`;

const text =
  `✅ *KONFIRMASI ABSENSI BERHASIL*\n` +
  `Halo, *${nama}*!\n\n` +
  `📌 *Jenis* : ${jenisDisplay}\n` +
  (infoWaktu ? `${infoWaktu}\n` : '') +
  `👤 *NIP*   : ${nip}\n` +
  `📍 *Lokasi*: ${lokasi}\n` +
  `📅 *Tgl*   : ${tanggal}\n` +
  `🕒 *Waktu* : ${jamBersih} WITA\n` +
  `${jamBatasInfo}\n\n` +
  `Terima kasih, selamat melanjutkan aktivitas!`;

return [{ json: { chat_id: chatId, text } }];
